create table public.subjects(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,name text not null,code text,created_at timestamptz not null default now(),unique(school_id,name));
create table public.teacher_subject_assignments(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,staff_id uuid not null references public.staff(id) on delete cascade,subject_id uuid not null references public.subjects(id) on delete cascade,academic_year_id uuid not null references public.academic_years(id) on delete cascade,class_id uuid not null references public.classes(id) on delete cascade,section_id uuid references public.sections(id) on delete cascade);
create table public.timetable_entries(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,academic_year_id uuid not null references public.academic_years(id),class_id uuid not null references public.classes(id),section_id uuid references public.sections(id),subject_id uuid not null references public.subjects(id),staff_id uuid references public.staff(id),weekday smallint not null check(weekday between 1 and 7),starts_at time not null,ends_at time not null,room text);
create table public.homework(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,academic_year_id uuid not null references public.academic_years(id),class_id uuid not null references public.classes(id),section_id uuid references public.sections(id),subject_id uuid references public.subjects(id),title text not null,description text,due_date date,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.notices(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,title text not null,body text not null,audience text not null default 'all',published boolean not null default true,created_by uuid references auth.users(id),created_at timestamptz not null default now());
alter table public.subjects enable row level security;alter table public.teacher_subject_assignments enable row level security;alter table public.timetable_entries enable row level security;alter table public.homework enable row level security;alter table public.notices enable row level security;
create policy "read subjects" on public.subjects for select using(public.is_school_member(school_id));create policy "manage subjects" on public.subjects for all using(public.can_manage_school(school_id)) with check(public.can_manage_school(school_id));
create policy "read tsa" on public.teacher_subject_assignments for select using(public.is_school_member(school_id));create policy "manage tsa" on public.teacher_subject_assignments for all using(public.can_manage_school(school_id)) with check(public.can_manage_school(school_id));
create policy "read timetable" on public.timetable_entries for select using(public.is_school_member(school_id));create policy "manage timetable" on public.timetable_entries for all using(public.can_manage_school(school_id)) with check(public.can_manage_school(school_id));
create policy "read homework" on public.homework for select using(public.is_school_member(school_id));create policy "manage homework" on public.homework for all using(public.is_school_member(school_id)) with check(public.is_school_member(school_id));
create policy "read notices" on public.notices for select using(public.is_school_member(school_id));create policy "manage notices" on public.notices for all using(public.can_manage_school(school_id)) with check(public.can_manage_school(school_id));